            errors.append(_failure("E1003", "Annual revenue negative"))

    if event == "UPDATE":
        old_credit_hold = _value(old, "CRED_HOLD")
        credit_hold = _value(record, "CRED_HOLD")
        credit_limit = _number(_value(record, "CRED_LIMIT"))

        if (
            old_credit_hold == "Y"
            and credit_hold == "N"
            and credit_limit <= Decimal(0)
        ):
            errors.append(
                _failure(
                    "E1004",
                    "Cannot release credit hold with zero credit limit",
                )
            )

    if event in ("INSERT", "UPDATE"):
        if _length(_value(record, "REGION_CD")) != 3:
            errors.append(
                _failure(
                    "E1005",
                    "Region code must be 3 chars",
                    "WARN",
                )
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
